import type { AnchorHTMLAttributes, CSSProperties, HTMLAttributes, LiHTMLAttributes, ReactNode, Ref } from "react";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

/** A responsive grid of gallery cards (a <ul>; give it an aria-label). */
export function GalleryGrid({ className, ...rest }: HTMLAttributes<HTMLUListElement>) {
  return <ul {...rest} className={cx("hm-gallery-grid", className)} />;
}

export type GalleryItemProps = LiHTMLAttributes<HTMLLIElement> & {
  /** Position in the grid, for the staggered entrance (capped at 12 so long lists do not wait). */
  index?: number;
};

/** One grid cell; staggers in on mount. */
export function GalleryItem({ index = 0, className, style, ...rest }: GalleryItemProps) {
  return (
    <li
      {...rest}
      className={cx("hm-gallery-item hm-enter", className)}
      style={{ "--hm-i": Math.min(index, 12), ...style } as CSSProperties}
    />
  );
}

export type GalleryCardProps = AnchorHTMLAttributes<HTMLAnchorElement> & {
  asChild?: boolean;
  ref?: Ref<HTMLAnchorElement>;
};

/** The whole card is one link: cover, title, meta. The cover zooms slowly and the title underlines on hover. */
export function GalleryCard({ asChild, className, ...rest }: GalleryCardProps) {
  const Comp = asChild ? Slot : "a";
  return <Comp {...(rest as object)} className={cx("hm-gallery-card", className)} />;
}

export type GalleryCoverProps = HTMLAttributes<HTMLSpanElement> & {
  /** Aspect ratio of the cover. Default 3 / 2. */
  ratio?: string;
  /** Pinned top-left over the image, usually a Badge with appearance="overlay". */
  badge?: ReactNode;
  /** Shown when there are no children (no photographs yet). */
  empty?: ReactNode;
};

export function GalleryCover({ ratio, badge, empty, className, style, children, ...rest }: GalleryCoverProps) {
  return (
    <span
      {...rest}
      className={cx("hm-gallery-cover", className)}
      style={{ ...(ratio ? { aspectRatio: ratio } : null), ...style }}
    >
      {children ?? <span className="hm-gallery-empty">{empty}</span>}
      {badge ? <span className="hm-gallery-badge">{badge}</span> : null}
    </span>
  );
}

export function GalleryTitle({ className, ...rest }: HTMLAttributes<HTMLElement>) {
  return <strong {...rest} className={cx("hm-gallery-title", className)} />;
}

export function GalleryMeta({ className, ...rest }: HTMLAttributes<HTMLElement>) {
  return <small {...rest} className={cx("hm-gallery-meta", className)} />;
}
